  ('160dd529-faf1-45f8-9257-b79feb26bd23', '7e104704-d383-4b37-bb66-58954da2caf0', null, 'topic'::public.curated_course_node_type, 'Network Architecture, Layering, and Internet Design Principles', 'This opening unit gives students the mental model for how networks are organized. It explains why layered design makes a global Internet possible while still allowing technologies to evolve independently.', 0),
